function Auth({setup,onAuth,onError}){const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[name,setName]=useState(''),[busy,setBusy]=useState(false);return <div className="auth-bg"><div className="auth-card"><div className="auth-logo">o</div><h1>OpenCRM</h1><p>{setup?'Создайте первый аккаунт администратора':'Войдите в рабочее пространство'}</p><form onSubmit={async e=>{e.preventDefault();setBusy(true);try{onAuth(await api(setup?'/setup':'/login',{method:'POST',body:setup?{name,email,password}:{email,password}}))}catch(err){onError(err)}finally{setBusy(false)}}}>{setup&&<label>Имя<input required value={name} onChange={e=>setName(e.target.value)} placeholder="Ваше имя"/></label>}<label>Email<input required type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@company.ru"/></label><label>Пароль<input required type="password" minLength={setup?10:1} value={password} onChange={e=>setPassword(e.target.value)} placeholder={setup?'Не менее 10 символов':'Пароль'}/></label><button className="blue-btn wide" disabled={busy}>{setup?'СОЗДАТЬ АККАУНТ':'ВОЙТИ'}</button></form><small>Данные хранятся на вашем сервере</small></div></div>}
function Empty({text}){return <div className="empty">{text}</div>}
function Stat({title,value,sub,danger}){return <div className="stat"><span>{title}</span><b className={danger?'danger':''}>{value}</b><small>{sub}</small></div>}
function Modal({type,initial,stages,users,groups,currentUser,deals,contacts,companies,pipelines,pipeline,onClose,onSave}){const defaults={name:'',title:'',amount:0,stage_id:initial?.stage_id||stages[0]?.id,owner_id:initial?.owner_id||currentUser.id,company_id:'',contact_id:'',pipeline_id:pipeline,source:'',tags:'',description:'',loss_reason:'',due_at:today(),duration_minutes:30,all_day:false,task_type:'Связаться',role:'member',deal_access:'all',task_access:'all',color:'#bcd3f6',entity_type:'deal',field_type:'text'};const [form,setForm]=useState({...defaults,...initial,...(type==='task'&&initial?.due_at?{due_at:localInput(initial.due_at)}:{})});const [busy,setBusy]=useState(false);const set=(key,val)=>setForm(f=>({...f,[key]:val}));const title={deal:initial?.id?'Изменить сделку':'Новая сделка',task:initial?.id?'Изменить задачу':'Новая задача',contact:initial?.id?'Изменить контакт':'Новый контакт',company:initial?.id?'Изменить компанию':'Новая компания',user:initial?.id?'Изменить сотрудника':'Новый сотрудник',pipeline:initial?.id?'Изменить воронку':'Новая воронка',stage:initial?.id?'Изменить этап':'Новый этап',customField:initial?.id?'Изменить поле':'Новое поле'}[type];const submit=async e=>{e.preventDefault();setBusy(true);const data={...form};if(type==='deal'){data.amount=Number(data.amount)||0;data.stage_id=Number(data.stage_id);data.owner_id=Number(data.owner_id)||null;data.company_id=Number(data.company_id)||null;data.contact_id=Number(data.contact_id)||null}if(type==='task'){data.owner_id=Number(data.owner_id)||null;data.deal_id=Number(data.deal_id)||null;data.contact_id=Number(data.contact_id)||null;data.company_id=Number(data.company_id)||null;if(data.due_at){const due=new Date(data.due_at);if(data.all_day)due.setHours(23,59,0,0);data.due_at=due.toISOString()}else data.due_at=null;data.duration_minutes=data.all_day?0:Number(data.duration_minutes)||0;data.all_day=!!data.all_day}if(type==='contact')data.company_id=Number(data.company_id)||null;if(type==='stage')data.pipeline_id=Number(data.pipeline_id);await onSave(data);setBusy(false)};const field=(label,key,props={})=><label key={key}>{label}<input value={form[key]??''} onChange={e=>set(key,e.target.value)} {...props}/></label>;const select=(label,key,opts)=><label key={key}>{label}<select value={form[key]??''} onChange={e=>setForm(current=>type==='task'&&['deal_id','contact_id','company_id'].includes(key)&&e.target.value?{...current,deal_id:'',contact_id:'',company_id:'',[key]:e.target.value}:{...current,[key]:e.target.value})}>{opts.map(([v,t])=><option value={v} key={v}>{t}</option>)}</select></label>;if(type==='task')return <TaskComposer initial={initial} users={users} currentUser={currentUser} deals={deals} contacts={contacts} companies={companies} onClose={onClose} onSave={onSave}/>;if(type==='deal'&&!initial?.id)return <NewDealForm stages={stages} users={users} currentUser={currentUser} contacts={contacts} companies={companies} onClose={onClose} onSave={onSave}/>;if(type==='customField')return <CustomFieldEditor initial={initial} onClose={onClose} onSave={onSave}/>;if(type==='user')return <UserEditor initial={initial} groups={groups} onClose={onClose} onSave={onSave}/>;return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal"><div className="modal-head"><h2>{title}</h2><button onClick={onClose}><X size={19}/></button></div><form onSubmit={submit} className="modal-form">{type==='deal'&&<>{field('Название сделки','name',{required:true,autoFocus:true})}{select('Этап','stage_id',stages.map(s=>[s.id,s.name]))}{stages.find(stage=>stage.id===Number(form.stage_id))?.kind==='lost'&&select('Причина отказа','loss_reason',lossReasons.map(reason=>[reason==='Без причины'?'':reason,reason]))}{field('Бюджет, ₽','amount',{type:'number',min:0})}{select('Ответственный','owner_id',users.map(u=>[u.id,u.name]))}{select('Контакт','contact_id',[['','—'],...contacts.map(c=>[c.id,c.name])])}{select('Компания','company_id',[['','—'],...companies.map(c=>[c.id,c.name])])}{field('Источник','source',{placeholder:'Сайт, рекомендация, outreach…'})}{field('Теги','tags',{placeholder:'Через запятую'})}<label>Описание<textarea value={form.description||''} onChange={e=>set('description',e.target.value)}/></label></>}{type==='task'&&<>{select('Тип задачи','task_type',[['Связаться','Связаться'],['Встреча','Встреча'],['Письмо','Письмо'],['Другое','Другое']])}{field('Что нужно сделать','title',{required:true,autoFocus:true})}<TaskScheduleFields form={form} set={set}/>{select('Ответственный','owner_id',users.map(u=>[u.id,u.name]))}{select('Сделка','deal_id',[['','—'],...deals.map(d=>[d.id,d.name]),...(initial?.deal_id&&!deals.some(d=>d.id===initial.deal_id)?[[initial.deal_id,'Сделка #'+initial.deal_id]]:[])])}{select('Контакт','contact_id',[['','—'],...contacts.map(c=>[c.id,c.name]),...(initial?.contact_id&&!contacts.some(c=>c.id===initial.contact_id)?[[initial.contact_id,'Контакт #'+initial.contact_id]]:[])])}{select('Компания','company_id',[['','—'],...companies.map(c=>[c.id,c.name]),...(initial?.company_id&&!companies.some(c=>c.id===initial.company_id)?[[initial.company_id,'Компания #'+initial.company_id]]:[])])}</>}{type==='contact'&&<>{field('Имя','name',{required:true,autoFocus:true})}{select('Компания','company_id',[['','—'],...companies.map(c=>[c.id,c.name])])}{select('Ответственный','owner_id',users.map(u=>[u.id,u.name]))}{field('Должность','position')}{field('Телефон','phone')}{field('Email','email',{type:'email'})}{field('Теги','tags',{placeholder:'Через запятую'})}<label>Примечание<textarea value={form.notes||''} onChange={e=>set('notes',e.target.value)}/></label></>}{type==='company'&&<>{field('Название компании','name',{required:true,autoFocus:true})}{select('Ответственный','owner_id',users.map(u=>[u.id,u.name]))}{field('Сайт','website')}{field('Адрес','address')}{field('Телефон','phone')}{field('Email','email',{type:'email'})}{field('Теги','tags',{placeholder:'Через запятую'})}<label>Примечание<textarea value={form.notes||''} onChange={e=>set('notes',e.target.value)}/></label></>}{type==='user'&&<>{field('Имя','name',{required:true,autoFocus:true})}{field('Email','email',{required:true,type:'email'})}{!initial?.id&&field('Пароль (от 10 символов)','password',{required:true,type:'password',minLength:10})}{select('Роль','role',[['member','Сотрудник'],['admin','Администратор']])}{form.role==='member'&&<>{select('Доступ к сделкам','deal_access',[['all','Все сделки'],['own','Если ответственный']])}{select('Доступ к задачам','task_access',[['all','Все задачи'],['own','Если ответственный']])}</>}</>}{type==='pipeline'&&field('Название воронки','name',{required:true,autoFocus:true})}{type==='customField'&&<>{!initial?.id&&select('Раздел','entity_type',[['deal','Сделка'],['contact','Контакт'],['company','Компания']])}{field('Название поля','name',{required:true,autoFocus:true})}{!initial?.id&&select('Тип','field_type',[['text','Текст'],['number','Число'],['date','Дата'],['url','Ссылка']])}</>}{type==='stage'&&<>{field('Название этапа','name',{required:true,autoFocus:true})}{field('Цвет','color',{type:'color'})}</>}<div className="modal-actions"><button type="button" onClick={onClose}>Отмена</button><button className="blue-btn" disabled={busy}>Сохранить</button></div></form></div></div>}

function UserEditor({initial,groups,onClose,onSave}){
  const [form,setForm]=useState({name:initial?.name||'',email:initial?.email||'',password:'',role:initial?.role||'member',deal_access:initial?.deal_access||'all',task_access:initial?.task_access||'all',contact_access:initial?.contact_access||'all',company_access:initial?.company_access||'all',group_id:initial?.group_id||'',permissions:initial?.permissions||{}});
  const [busy,setBusy]=useState(false);
  const set=(key,value)=>setForm(current=>({...current,[key]:value}));
  const setPermission=(entity,action,enabled)=>setForm(current=>({...current,permissions:{...current.permissions,[entity]:{...current.permissions[entity],[action]:enabled}}}));
  const submit=async event=>{event.preventDefault();setBusy(true);try{await onSave(initial?.id?{name:form.name,email:form.email,role:form.role,deal_access:form.deal_access,task_access:form.task_access,contact_access:form.contact_access,company_access:form.company_access,group_id:Number(form.group_id)||null,permissions:form.permissions}:{...form,group_id:Number(form.group_id)||null})}finally{setBusy(false)}};
  const matrix=[['deal','Сделки / Покупатели','deal_access'],['contact','Контакты','contact_access'],['company','Компании','company_access'],['task','Задачи','task_access']];
  const accessCell=(entity,action)=>entity==='task'&&action==='export'?<span className="user-rights-unavailable" title="Это действие недоступно для задач">—</span>:<button type="button" className={'user-permission-button '+(form.permissions?.[entity]?.[action]===false?'denied':'granted')} aria-label={`${action==='create'?'Создание':action==='edit'?'Правка':action==='delete'?'Удаление':'Экспорт'}: ${entity}`} aria-pressed={form.permissions?.[entity]?.[action]!==false} title={form.permissions?.[entity]?.[action]===false?'Запрещено':'Разрешено'} onClick={()=>setPermission(entity,action,form.permissions?.[entity]?.[action]===false)}>{form.permissions?.[entity]?.[action]===false?'×':'✓'}</button>;
  return <div className="modal-backdrop user-rights-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)onClose()}}><aside className="user-rights-panel"><form onSubmit={submit}><header className="user-rights-top"><button type="button" onClick={onClose}>Отменить</button><button className="user-rights-save" disabled={busy}>{busy?'Сохраняем…':'Сохранить'}</button></header><div className="user-rights-scroll"><section className="user-profile-card"><div className="user-avatar">{(form.name||'?').trim().slice(0,1).toUpperCase()}</div><div className="user-profile-fields"><label>Имя<input required maxLength={120} value={form.name} onChange={event=>set('name',event.target.value)}/></label><label>Email<input required type="email" maxLength={254} value={form.email} onChange={event=>set('email',event.target.value)}/></label><label>Группа<select value={form.group_id} onChange={event=>set('group_id',event.target.value)}><option value="">Без группы</option>{groups.map(group=><option key={group.id} value={group.id}>{group.name}</option>)}</select></label>{!initial?.id&&<label>Пароль<input required type="password" minLength={10} value={form.password} onChange={event=>set('password',event.target.value)} placeholder="Не менее 10 символов"/></label>}</div></section><div className="user-role-switch"><button type="button" className={form.role==='admin'?'active':''} onClick={()=>set('role','admin')}>Администратор</button><button type="button" className={form.role==='member'?'active':''} onClick={()=>set('role','member')}>Свои права</button></div>{form.role==='member'?<section className="user-rights-card"><div className="user-rights-matrix"><div className="user-rights-heading"><strong>РАЗДЕЛ</strong><strong>СОЗДАНИЕ</strong><strong>ПРОСМОТР</strong><strong>ПРАВКА</strong><strong>УДАЛЕНИЕ</strong><strong>ЭКСПОРТ</strong></div>{matrix.map(([entity,label,scope])=><div className="user-rights-row" key={entity}><strong>{label}</strong>{accessCell(entity,'create')}<div className="user-rights-view">{scope?<select aria-label={`Просмотр: ${label}`} value={form[scope]} onChange={event=>set(scope,event.target.value)}><option value="all">Разрешено</option><option value="own">Если ответственный</option></select>:<span>Разрешено</span>}</div>{accessCell(entity,'edit')}{accessCell(entity,'delete')}{accessCell(entity,'export')}</div>)}</div><p>Зелёная отметка разрешает действие, крестик запрещает. Просмотр сделок, контактов, компаний и задач можно ограничить ответственным.</p></section>:<section className="user-rights-card user-admin-note">Администратор имеет полный доступ ко всем разделам и настройкам.</section>}</div></form></aside></div>;
}

createRoot(document.getElementById('root')).render(<App/>);
